report <- function(expr) {
    tryCatch(eval(substitute(expr),parent.frame()),error=function(e) {
        cat(conditionMessage(e),'\n',sep='')
        cat(paste(deparse(conditionCall(e)),collapse=' '),'\n',sep='')
    })
}
report(rep_len(1L,-1L))
report(rep_len(1L,NA_integer_))
report(rep_len(1L,Inf))
report(rep_len(1L,integer(0)))
report(rep_len(1L,c(2L,3L)))
print(identical(rep_len(1L,-0.5),integer(0)))
print(identical(rep_len(c(a=1L,b=2L),5L),c(1L,2L,1L,2L,1L)))
print(identical(rep_len(character(0),2L),c(NA_character_,NA_character_)))
print(identical(rep_len(list(1L,TRUE),3L),list(1L,TRUE,1L)))
print(identical(rep_len(list(),2L),list(NULL,NULL)))
print(identical(rep_len(expression(),2L),expression(NULL,NULL)))
print(identical(rep_len(complex(0),2L),c(NA_complex_,NA_complex_)))
print(identical(local({x<-character(0);length(x)<-2L;x}),c(NA_character_,NA_character_)))
local({
    f <- tempfile()
    on.exit(unlink(f))
    writeLines(c('123','456'),f)
    report(read.fwf(f,widths=integer(0)))
    expected <- data.frame(V1=c(12L,45L),V2=c(3L,6L))
    print(identical(read.fwf(f,widths=c(2L,1L)),expected))
})
print(is.function(get("rep.int",baseenv(),inherits=FALSE)))
print(is.function(get("rep_len",baseenv(),inherits=FALSE)))
print(identical(environment(rep.int),asNamespace("base")))
print(identical(environment(rep_len),asNamespace("base")))
print(identical(as.list(formals(rep.int)),alist(x=,times=)))
print(identical(as.list(formals(rep_len)),alist(x=,length.out=)))
print(identical(body(rep.int),quote(.Internal(rep.int(x,times)))))
print(identical(body(rep_len),quote(.Internal(rep_len(x,length.out)))))
print(identical(compiler::cmpfun(function(x)rep_len(x,3L))(1:2),c(1L,2L,1L)))
report(rep_len(NULL,3L))
report(rep_len(new.env(),3L))
report(rep.int(1:2,-1L))
report(rep.int(1:2,integer(0)))
report(rep.int(1:2,c(1L,-1L)))
report(rep.int(1:2,new.env()))
report(rep.int(new.env(),2L))
compiled_error <- compiler::cmpfun(function()rep_len(1L,-1L))
report(compiled_error())
captured <- tryCatch(compiled_error(),error=function(e){invisible(gc());conditionCall(e)})
print(identical(captured,quote(rep_len(1L,-1L))))
observed_depth <- compiler::cmpfun(function()sys.nframe())()
print(observed_depth)
print(identical(rep_len(1L,3L),c(1L,1L,1L)))
local({
    hits <- 0L
    observe <- compiler::cmpfun(function(x){invisible(gc());list(call=sys.call(),code=substitute(x),value=x)})
    result <- observe({hits<-hits+1L;2L})
    print(identical(result$call,quote(observe({hits<-hits+1L;2L}))))
    print(identical(result$code,quote({hits<-hits+1L;2L})))
    print(identical(result$value,2L))
    print(identical(hits,1L))
})
